import sys
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T_str = next(iterator)
        T = int(T_str)
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
            X = int(next(iterator))
            M = int(next(iterator))
            S = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(N + 1)]

        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u].append((v, w))
            adj[v].append((u, w))

        INF = float('inf')
        dist = [INF] * (N + 1)
        dist[S] = 0

        pq = [(0, S)]

        old_cities = set(range(1, K + 1))

        min_dist_to_old_cluster = INF
        best_entry_city = -1

        while pq:
            d, u = heapq.heappop(pq)

            if d > dist[u]:
                continue

            if u <= K:
                if d < min_dist_to_old_cluster:
                    min_dist_to_old_cluster = d
                    best_entry_city = u

            for v, w in adj[u]:
                new_dist = d + w
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(pq, (new_dist, v))

        if min_dist_to_old_cluster != INF:
            for city in range(1, N + 1):
                if city <= K:
                    potential = min_dist_to_old_cluster + X
                    if potential < dist[city]:
                        dist[city] = potential
                        heapq.heappush(pq, (potential, city))

        final_distances = []
        for i in range(1, N + 1):
            final_distances.append(str(dist[i]))

        print(" ".join(final_distances))

if __name__ == "__main__":
    solve()
